  join clubs c on c.id = a.club_id


  
    and a.club_id = #{clubId}
  
  
    and a.club_id in
    
      #{cid}
    
  
  
    and c.club_name like concat('%', #{clubName}, '%')
  
  
    and a.activity_name like concat('%', #{keyword}, '%')
  
  
    and a.status = #{status}

select a.id, a.club_id, a.activity_name, a.activity_type, a.description, a.start_time, a.end_time, a.location, a.max_participants, a.current_participants, a.registration_deadline, a.status, a.creator_id, a.created_time, a.updated_time from activities a
join clubs c on c.id = a.club_id
and a.club_id = #{clubId}
and a.club_id in
#{cid}
