mapper.update:
update activities
activity_name = #{activityName}, activity_type = #{activityType}, description = #{description}, start_time = #{startTime}, end_time = #{endTime}, location = #{location}, max_participants = #{maxParticipants}, current_participants = #{currentParticipants}, registration_deadline = #{registrationDeadline}, status = #{status},
